class Solution {
public:
    vector<int> fullBloomFlowers(vector<vector<int>>& flowers, vector<int>& people) {
        vector<int> starts, ends;
        for (const auto& f : flowers) {
            starts.push_back(f[0]);
            ends.push_back(f[1]);
        }
        sort(starts.begin(), starts.end());
        sort(ends.begin(), ends.end());
        vector<int> ans;
        for (int t : people) {
            int started = upper_bound(starts.begin(), starts.end(), t) - starts.begin();
            int finished = lower_bound(ends.begin(), ends.end(), t) - ends.begin();
            ans.push_back(started - finished);
        }
        return ans;
    }
};

class Solution {
    public int[] fullBloomFlowers(int[][] flowers, int[] people) {
        int n = flowers.length;
        int[] starts = new int[n];
        int[] ends = new int[n];
        for (int i = 0; i < n; i++) {
            starts[i] = flowers[i][0];
            ends[i] = flowers[i][1];
        }
        Arrays.sort(starts);
        Arrays.sort(ends);
        int[] ans = new int[people.length];
        for (int i = 0; i < people.length; i++) {
            int t = people[i];
            int started = bisectRight(starts, t);
            int finished = bisectLeft(ends, t);
            ans[i] = started - finished;
        }
        return ans;
    }

    private int bisectRight(int[] arr, int target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int mid = (l + r) / 2;
            if (arr[mid] <= target) l = mid + 1;
            else r = mid;
        }
        return l;
    }

    private int bisectLeft(int[] arr, int target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int mid = (l + r) / 2;
            if (arr[mid] < target) l = mid + 1;
            else r = mid;
        }
        return l;
    }
}

/**
 * @param {number[][]} flowers
 * @param {number[]} people
 * @return {number[]}
 */
var fullBloomFlowers = function(flowers, people) {
    const starts = flowers.map(f => f[0]).sort((a, b) => a - b);
    const ends = flowers.map(f => f[1]).sort((a, b) => a - b);

    const bisectRight = (arr, target) => {
        let l = 0, r = arr.length;
        while (l < r) {
            const mid = (l + r) >> 1;
            if (arr[mid] <= target) l = mid + 1;
            else r = mid;
        }
        return l;
    };

    const bisectLeft = (arr, target) => {
        let l = 0, r = arr.length;
        while (l < r) {
            const mid = (l + r) >> 1;
            if (arr[mid] < target) l = mid + 1;
            else r = mid;
        }
        return l;
    };

    return people.map(t => bisectRight(starts, t) - bisectLeft(ends, t));
};
